    "bu.noAnalysisText": { de: "Die Burnout-Prävention analysiert automatisch Nachtschichten, Überstunden, Pausenverstöße und Fehlzeiten-Muster deiner Mitarbeiter. Sobald die Schichtdaten verbunden sind, erhältst du ein kontinuierliches Frühwarnsystem — und siehst 3–6 Wochen im Voraus, wer gefährdet ist.", en: "Burnout prevention automatically analyses night shifts, overtime, break violations and absence patterns of your staff. Once shift data is connected, you get a continuous early warning system — and see 3–6 weeks in advance who is at risk.", tr: "Tükenmişlik önleme sistemi gece vardiyalarını, fazla mesaileri, mola ihlallerini ve devamsızlık örüntülerini otomatik olarak analiz eder.", pl: "System profilaktyki wypalenia automatycznie analizuje zmiany nocne, nadgodziny, naruszenia przerw i wzorce nieobecności pracowników.", ro: "Prevenirea burnout analizează automat turele de noapte, orele suplimentare, încălcările pauzelor și tiparele de absențe ale angajaților.", ar: "يحلل نظام الوقاية من الإرهاق تلقائيًا الورديات الليلية والعمل الإضافي وانتهاكات الاستراحة وأنماط الغياب.", ru: "Профилактика выгорания автоматически анализирует ночные смены, переработки, нарушения перерывов и шаблоны отсутствий сотрудников." },
    "bu.connectLink": { de: "Schichtdaten verbinden →", en: "Connect shift data →", tr: "Vardiya verilerini bağla →", pl: "Połącz dane zmian →", ro: "Conectează datele →", ar: "ربط بيانات الورديات →", ru: "Подключить данные смен →" },
    "bu.pitch": { de: "«Nurvo warnt dich 3 Wochen bevor dein bestes Personal kündigt.»", en: "«Nurvo warns you 3 weeks before your best staff quit.»", tr: "«Nurvo, en iyi personeliniz ayrılmadan 3 hafta önce sizi uyarır.»", pl: "«Nurvo ostrzega cię 3 tygodnie przed odejściem najlepszych pracowników.»", ro: "«Nurvo te avertizează cu 3 săptămâni înainte ca cel mai bun personal să plece.»", ar: "«ينبهك نورفو قبل 3 أسابيع من مغادرة أفضل موظفيك.»", ru: "«Nurvo предупредит тебя за 3 недели до того, как уйдёт лучший сотрудник.»" },
    "bu.pitchText": { de: "Nurvo wertet kontinuierlich Nachtschichten, Überstunden, Pausenverstöße und Fehlzeiten-Muster aus — und schlägt proaktiv Entlastungsmaßnahmen vor.", en: "The AI continuously analyses night shifts, overtime, break violations and absence patterns — and proactively suggests relief measures.", tr: "Yapay zeka gece vardiyalarını, fazla mesaileri, mola ihlallerini ve devamsızlık örüntülerini sürekli analiz eder ve proaktif rahatlama önlemleri önerir.", pl: "AI ciągle analizuje zmiany nocne, nadgodziny, naruszenia przerw i wzorce nieobecności — i proaktywnie sugeruje środki zaradcze.", ro: "AI analizează continuu turele de noapte, orele suplimentare, încălcările pauzelor și tiparele de absențe — și sugerează proactiv măsuri de ameliorare.", ar: "يحلل الذكاء الاصطناعي باستمرار الورديات الليلية والعمل الإضافي وانتهاكات الاستراحة وأنماط الغياب ويقترح إجراءات تخفيفية.", ru: "ИИ непрерывно анализирует ночные смены, переработки, нарушения перерывов и паттерны отсутствий — и проактивно предлагает меры по снижению нагрузки." },
    "cert.title": { de: "Qualifikationen & Zertifikate", en: "Qualifications & Certificates", tr: "Yeterlilikler ve Sertifikalar", pl: "Kwalifikacje i certyfikaty", ro: "Calificări și certificate", ar: "المؤهلات والشهادات", ru: "Квалификации и сертификаты" },
    "cert.subtitle": { de: "Nachweise mit Ablaufdatum im Blick — Nurvo erinnert vor dem Ablauf", en: "Keep track of certificates with expiry dates — Nurvo reminds you before they expire", tr: "Son kullanma tarihli belgeler — Nurvo süre dolmadan hatırlatır", pl: "Certyfikaty z datą ważności — Nurvo przypomina przed wygaśnięciem", ro: "Certificate cu dată de expirare — Nurvo amintește înainte de expirare", ar: "الشهادات وتواريخ انتهائها — يذكّرك نورفو قبل الانتهاء", ru: "Сертификаты со сроком действия — Nurvo напомнит заранее" },
    "cert.expired": { de: "Abgelaufen", en: "Expired", tr: "Süresi dolmuş", pl: "Wygasłe", ro: "Expirat", ar: "منتهية الصلاحية", ru: "Истёкшие" },
