    "cert.overview": { de: "Zertifikats-Übersicht", en: "Certificate overview", tr: "Sertifika özeti", pl: "Przegląd certyfikatów", ro: "Prezentare certificate", ar: "نظرة عامة على الشهادات", ru: "Обзор сертификатов" },
    "cert.add": { de: "Zertifikat hinzufügen", en: "Add certificate", tr: "Sertifika ekle", pl: "Dodaj certyfikat", ro: "Adaugă certificat", ar: "إضافة شهادة", ru: "Добавить сертификат" },
    "cert.none": { de: "Noch keine Zertifikate erfasst", en: "No certificates added yet", tr: "Henüz sertifika eklenmedi", pl: "Brak certyfikatów", ro: "Niciun certificat adăugat", ar: "لا توجد شهادات بعد", ru: "Сертификаты ещё не добавлены" },
    "cert.noneHint": { de: "Lege Nachweise mit Ablaufdatum an. Nurvo erinnert die Person und dich 90 und 30 Tage vorher und am Tag des Ablaufs.", en: "Add certificates with an expiry date. Nurvo reminds the person and you 90 and 30 days before and on the day they expire.", tr: "Son kullanma tarihli belgeler ekleyin. Nurvo kişiye ve size 90 ve 30 gün önce ve son gün hatırlatır.", pl: "Dodaj certyfikaty z datą ważności. Nurvo przypomni osobie i Tobie 90 i 30 dni wcześniej oraz w dniu wygaśnięcia.", ro: "Adaugă certificate cu dată de expirare. Nurvo amintește persoanei și ție cu 90 și 30 de zile înainte și în ziua expirării.", ar: "أضف الشهادات مع تاريخ الانتهاء. يذكّر نورفو الشخص وإياك قبل 90 و30 يومًا وفي يوم الانتهاء.", ru: "Добавьте сертификаты со сроком действия. Nurvo напомнит сотруднику и вам за 90 и 30 дней и в день окончания." },
    "cert.smart": { de: "Smart-Schichtbesetzung", en: "Smart shift assignment", tr: "Akıllı vardiya ataması", pl: "Inteligentne przypisywanie zmian", ro: "Alocare inteligentă ture", ar: "تعيين ذكي للورديات", ru: "Умное назначение смен" },
    "cert.smartText": { de: "Nurvo weist Schichten automatisch nur mit qualifiziertem Personal zu. Abgelaufene Zertifikate führen zur sofortigen Sperrung für betroffene Schichttypen.", en: "Nurvo assigns shifts only to qualified staff. Expired certificates trigger immediate lock-out for affected shift types.", tr: "Nurvo vardiyaları yalnızca nitelikli personele atar. Süresi dolan sertifikalar ilgili vardiya türleri için kilidi etkinleştirir.", pl: "Nurvo przypisuje zmiany tylko wykwalifikowanemu personelowi. Wygasłe certyfikaty powodują zablokowanie dla danych typów zmian.", ro: "Nurvo alocă turele doar personalului calificat. Certificatele expirate duc la blocare imediată.", ar: "يعيّن نورفو الورديات لموظفين مؤهلين فقط. تؤدي الشهادات المنتهية إلى قفل فوري.", ru: "Nurvo назначает смены только квалифицированному персоналу. Просроченные сертификаты ведут к немедленной блокировке." },
    "cert.supported": { de: "Unterstützte Zertifikate", en: "Supported certificates", tr: "Desteklenen sertifikalar", pl: "Obsługiwane certyfikaty", ro: "Certificate suportate", ar: "الشهادات المدعومة", ru: "Поддерживаемые сертификаты" },
