    "fp.noAvailSub": { de: "Trag ein, wann du als Springer einspringen kannst.", en: "Add when you can step in as a floater.", tr: "Gezici olarak ne zaman devreye girebileceğini ekle.", pl: "Dodaj, kiedy możesz zastąpić.", ro: "Adaugă când poți interveni ca supleant.", ar: "أضِف متى يمكنك التدخّل كمتنقّل.", ru: "Укажите, когда вы можете подменить как резерв." },
