    "fp.selfReportOn": { de: "Mitarbeiter können sich selbst krank melden", en: "Staff can report themselves sick", tr: "Personel kendini hasta bildirebilir", pl: "Personel może sam zgłaszać chorobę", ro: "Personalul se poate raporta bolnav", ar: "يمكن للموظفين الإبلاغ عن مرضهم", ru: "Сотрудники могут сами сообщать о болезни" },
