    "fp.noAgenciesSub": { de: "Füge Pflegedienste hinzu, die bei Unterbesetzung automatisch kontaktiert werden.", en: "Add care agencies to be contacted automatically when understaffed.", tr: "Yetersiz kadroda otomatik iletişim kurulacak bakım hizmetleri ekleyin.", pl: "Dodaj agencje opieki, z którymi skontaktujemy się automatycznie przy niedoborze.", ro: "Adaugă agenții de îngrijire care vor fi contactate automat la personal insuficient.", ar: "أضِف خدمات رعاية يتم التواصل معها تلقائيًا عند نقص الكادر.", ru: "Добавьте службы ухода, с которыми свяжутся автоматически при нехватке." },
    "fp.agencyStep1": { de: "Pflegedienst mit E-Mail hinzufügen", en: "Add a care agency with email", tr: "E-posta ile bakım hizmeti ekle", pl: "Dodaj agencję opieki z e-mailem", ro: "Adaugă o agenție cu e-mail", ar: "أضِف خدمة رعاية مع بريد إلكتروني", ru: "Добавьте службу с эл. почтой" },
    "fp.agencyStep2": { de: "Bei Unterbesetzung: „Externe anfragen“ klicken", en: "When understaffed: click “Request external”", tr: "Yetersiz kadroda: „Harici iste“ tıkla", pl: "Przy niedoborze: kliknij „Poproś zewnętrznych“", ro: "La personal insuficient: apasă „Solicită extern“", ar: "عند نقص الكادر: انقر „طلب خارجي“", ru: "При нехватке: нажмите «Запросить внешних»" },
    "fp.agencyStep3": { de: "Dienst antwortet per E-Mail — du wirst benachrichtigt", en: "The agency replies by email — you get notified", tr: "Hizmet e-posta ile yanıtlar — bilgilendirilirsin", pl: "Agencja odpowiada e-mailem — otrzymasz powiadomienie", ro: "Agenția răspunde prin e-mail — ești notificat", ar: "ترد الخدمة عبر البريد الإلكتروني — سيتم إعلامك", ru: "Служба отвечает по эл. почте — вы получите уведомление" },
