export type TKey = keyof typeof T;
type Ctx = {
    lang: Lang;
    setLang: (l: Lang) => void;
    t: (k: TKey) => string;
    locale: string;
};
const LangCtx = createContext<Ctx>({ lang: "de", setLang: () => { }, t: (k) => T[k]?.de ?? k, locale: "de-DE" });
const SPRACHE_SCHLUESSEL = "nurvo_lang";
const hoerer = new Set<() => void>();
function melden() {
    for (const h of hoerer)
        h();
}
function abonnieren(h: () => void) {
    hoerer.add(h);
    window.addEventListener("storage", h);
    return () => {
        hoerer.delete(h);
        window.removeEventListener("storage", h);
    };
}
function lesen(): Lang {
    try {
        const g = localStorage.getItem(SPRACHE_SCHLUESSEL) as Lang | null;
        if (g && LANGUAGES.some(l => l.code === g))
            return g;
    }
    catch { }
    return "de";
}
const SERVER_SPRACHE: Lang = "de";
const serverLesen = () => SERVER_SPRACHE;
export function LanguageProvider({ children }: {
    children: React.ReactNode;
}) {
    const lang = useSyncExternalStore(abonnieren, lesen, serverLesen);
    const setLang = useCallback((l: Lang) => {
        try {
            localStorage.setItem(SPRACHE_SCHLUESSEL, l);
        }
        catch { }
        melden();
    }, []);
    const praxis = usePlanRoh() === "praxis";
    const t = (k: TKey): string => (praxis ? praxisText(k, lang) : undefined) ?? (T[k] as Record<Lang, string>)?.[lang] ?? T[k]?.de ?? k;
    const locale = LANG_TO_LOCALE[lang];
    return <LangCtx.Provider value={{ lang, setLang, t, locale }}>{children}</LangCtx.Provider>;
}
export const useLang = () => useContext(LangCtx);
